//! Armada's protocol (`api/armada/v1`) and the part of etcd's API Armada
//! uses (ADR 0055), as Rust types, gRPC clients and servers, and protobuf
//! JSON.
//!
//! The code in `src/gen` is generated by `make proto` (`proto/gen`, with
//! prost-build, tonic-prost-build, and pbjson-build at the versions the
//! workspace pins) and checked in, so building needs no protoc. Never edit
//! it by hand.
//!
//! - Maps are `BTreeMap`s: the binary encoding writes their entries sorted
//!   by key, as Go's deterministic encoding does, and their JSON comes out
//!   in the order Go's protojson writes it.
//! - The JSON (`serde`, from pbjson) is protojson's: lowerCamelCase names,
//!   default values left out, 64-bit integers as strings, enums by name,
//!   bytes in standard base64, and timestamps in RFC 3339 with a `Z`
//!   (`google::protobuf::Timestamp`, armada-proto's own: pbjson-types writes
//!   `+00:00`).
//! - etcd's services are clients only.

mod timestamp;

/// The well-known types Armada's protocol uses.
pub mod google {
    /// `google.protobuf`.
    pub mod protobuf {
        pub use crate::timestamp::Timestamp;
    }
}

/// Armada's own protocol.
pub mod armada {
    /// `armada.v1`: AdminService, AgentService, JoinService, and their
    /// messages.
    #[allow(
        clippy::all,
        clippy::pedantic,
        missing_docs,
        rustdoc::all,
        unreachable_pub
    )]
    pub mod v1 {
        include!("gen/armada.v1.rs");
        include!("gen/armada.v1.serde.rs");
    }
}

/// etcd's API (go.etcd.io/etcd/api/v3, vendored in `proto/vendor` under
/// the Apache License 2.0): KV, Watch, Lease, Cluster, and Maintenance.
pub mod etcd {
    /// `mvccpb`: keys, values, and watch events.
    #[allow(clippy::all, clippy::pedantic, missing_docs, rustdoc::all)]
    pub mod mvccpb {
        include!("gen/mvccpb.rs");
    }

    /// `etcdserverpb`: the requests, responses, and service clients.
    #[allow(clippy::all, clippy::pedantic, missing_docs, rustdoc::all)]
    pub mod etcdserverpb {
        include!("gen/etcdserverpb.rs");
    }
}
